diagram.source:
direction: right
ui: UI { icon: gnosis:user }
owner: "Snapshots instance — in memory" {
  direction: down
  heads: "heads[pr]: current head"
  refresh: "refresh(pr)\nCapture requestedHead"
  guard: "Response gate\ncurrent head === requestedHead?" {
    tooltip: "This compares head values, not request identities or generations."
  }
  cache: "snapshots[pr]: last accepted snapshot"
  discard: "Discard response\nKeep existing snapshot"
  heads -> refresh: capture head
  heads -> guard: read head again after await
  guard -> cache: "equal: replace snapshot"
  guard -> discard: "different: return"
}
github: GitHub { icon: gnosis:cloud }
ui -> owner.heads: setHead(pr, head)
ui -> owner.cache: "read(pr): immediate lookup"
owner.refresh -> github: load(pr, requestedHead)
github -> owner.guard: resolved snapshot
scenarios: {
  stale: {
    owner.heads.label: "heads[pr]: B"
    owner.refresh.label: "Request captured A"
    owner.guard.label: "B !== A"
    owner.discard.style.stroke-width: 4
    (owner.guard -> owner.discard)[0].style.stroke-width: 4
    owner.cache.tooltip: "Discarding this response leaves the previous snapshot available to read(pr), even if that snapshot belongs to an older head."
  }
  matching: {
    owner.heads.label: "heads[pr]: B"
    owner.refresh.label: "Request captured B"
    owner.guard.label: "B === B"
    owner.cache.style.stroke-width: 4
    (owner.guard -> owner.cache)[0].style.stroke-width: 4
  }
}
